func (l *Lease) Renew(ctx context.Context) error {
    ticker := time.NewTicker(l.interval)
    for { select { case <-ticker.C: if err := l.store.Extend(ctx, l.key, l.ttl); err != nil { return err }; case <-ctx.Done(): return ctx.Err() } }
}

